using System;
using System.Reflection;

// PROGRAM: Menginspeksi Kode Intermediate Language (IL) secara Dinamis
Console.WriteLine("=== INSPEKSI RUNTIME IL BYTECODE ===");

// Mendapatkan method Math.Max via Reflection
var method = typeof(Math).GetMethod("Max", new[] { typeof(int), typeof(int) });
if (method != null)
{
    var body = method.GetMethodBody();
    if (body != null)
    {
        byte[] ilBytes = body.GetILAsByteArray() ?? Array.Empty<byte>();
        Console.WriteLine($"Method: {method.Name}(int, int)");
        Console.WriteLine($"Ukuran IL Bytecode: {ilBytes.Length} byte");
        Console.Write("Raw IL Opcode: ");
        foreach (var b in ilBytes)
        {
            Console.Write($"0x{b:X2} ");
        }
        Console.WriteLine();
    }
}

