using System;
using System.Collections.Generic;

public class StackMachine
{
    public static int Evaluate(string[] opcodes)
    {
        if (opcodes == null) return 0;
        var stack = new Stack<int>();

        foreach (var op in opcodes)
        {
            if (string.IsNullOrWhiteSpace(op)) continue;
            var parts = op.Trim().Split(' ', StringSplitOptions.RemoveEmptyEntries);
            string cmd = parts[0].ToUpperInvariant();

            if (cmd == "PUSH" && parts.Length > 1 && int.TryParse(parts[1], out int val))
            {
                stack.Push(val);
            }
            else if (cmd == "ADD" && stack.Count >= 2)
            {
                int b = stack.Pop();
                int a = stack.Pop();
                stack.Push(a + b);
            }
            else if (cmd == "MUL" && stack.Count >= 2)
            {
                int b = stack.Pop();
                int a = stack.Pop();
                stack.Push(a * b);
            }
        }

        return stack.Count > 0 ? stack.Peek() : 0;
    }

    public static void Main()
    {
        string[] program = { "PUSH 5", "PUSH 3", "ADD", "PUSH 2", "MUL" };
        Console.WriteLine($"Hasil: {Evaluate(program)}");
    }
}
